const C={bg:'#FAF7F2',paper:'#FFFFFF',ink:'#1F2933',muted:'#64707A',line:'#E8E0D5',soft:'#F3ECE2',primary:'#A16207',hover:'#92400E',accent:'#F59E0B',pale:'#FFF0D6',green:'#346B5B'};
const rgb=h=>({r:parseInt(h.slice(1,3),16)/255,g:parseInt(h.slice(3,5),16)/255,b:parseInt(h.slice(5,7),16)/255});
