const made=[];
function box(parent,name,x,y,w,h,color=C.paper,r=0){const n=figma.createFrame();n.name=name;n.x=x;n.y=y;n.resize(w,h);n.fills=paint(color);n.cornerRadius=r;n.clipsContent=true;parent.appendChild(n);made.push(n.id);return n;}
function line(parent,x,y,w,color=C.line){const n=figma.createRectangle();n.name='Разделитель';n.x=x;n.y=y;n.resize(w,1);n.fills=paint(color);parent.appendChild(n);return n;}
function textNode(parent,s,x,y,w,size=16,color=C.ink,bold=false){const n=figma.createText();n.name=s.slice(0,55);n.fontName={family:'Arimo',style:bold?'Bold':'Regular'};n.characters=s;n.fontSize=size;n.fills=paint(color);n.textAutoResize='HEIGHT';n.x=x;n.y=y;n.resize(w,n.height);parent.appendChild(n);return n;}
function pill(parent,s,x,y,w,color=C.soft,ink=C.ink){const n=box(parent,'Тег · '+s,x,y,w,32,color,16);textNode(n,s,13,7,w-26,13,ink,true);return n;}
function photo(parent,index,x,y,w,h,r=16){const n=box(parent,'Фото комнаты '+(index+1),x,y,w,h,['#D9C3A8','#C7B49B','#DDC9AF'][index%3],r);n.fills=[{type:'IMAGE',scaleMode:'FILL',imageHash:IMAGE_HASHES[index%3]}];return n;}
function avatar(parent,initial,x,y,size=42){const n=box(parent,'Аватар '+initial,x,y,size,size,C.pale,size/2);textNode(n,initial,size/2-8,size/2-12,20,20,C.primary,true);return n;}
function button(parent,s,x,y,w=190,h=46,kind='primary'){const n=buttonComponent.createInstance();n.name='Кнопка · '+s;n.x=x;n.y=y;n.resize(w,h);n.fills=paint(kind==='primary'?C.primary:C.paper);n.strokes=kind==='primary'?[]:paint(C.line);n.cornerRadius=12;const t=n.findOne(q=>q.type==='TEXT');if(t){t.characters=s;t.fills=paint(kind==='primary'?C.paper:C.ink);}parent.appendChild(n);return n;}
function header(s,active){const h=box(s,'Шапка',0,0,1440,78,C.paper);line(h,0,77,1440);textNode(h,'GETSOSED',74,25,190,22,C.ink,true);const items=[['Главная',335],['Найти жильё',460],['О нас',620],['Сообщения',730]];for(const [label,x] of items)textNode(h,label,x,30,155,15,label===active?C.primary:C.ink,label===active);button(h,'Разместить объявление',1050,16,240,46,'primary');avatar(h,'А',1330,18,42);}
function screen(name,x,y,h){const s=box(page,name,x,y,1440,h,C.bg,0);header(s,name==='Главная'?'Главная':name==='Поиск жилья'?'Найти жильё':name==='О нас'?'О нас':name==='Сообщения'?'Сообщения':'');return s;}
function caption(parent,s,x,y,w){textNode(parent,s.toUpperCase(),x,y,w,13,C.primary,true);}
function heading(parent,s,x,y,w,size=42){textNode(parent,s,x,y,w,size,C.ink,true);}
function sub(parent,s,x,y,w,size=16){textNode(parent,s,x,y,w,size,C.muted,false);}
function input(parent,label,value,x,y,w){textNode(parent,label,x,y,w,14,C.ink,true);const n=box(parent,'Поле · '+label,x,y+25,w,48,C.paper,10);n.strokes=paint(C.line);textNode(n,value,15,14,w-30,15,C.ink);return n;}

