function listing(parent,item,index,x,y,w=370){const n=cardComponent.createInstance();n.name='Объявление · '+item.title;n.x=x;n.y=y;n.resize(w,442);n.children.find(c=>c.name==='Фото').fills=[{type:'IMAGE',scaleMode:'FILL',imageHash:IMAGE_HASHES[index%3]}];const ts=n.findAll(c=>c.type==='TEXT');ts.find(c=>c.characters.includes('25 000')).characters=item.price;ts.find(c=>c.characters.includes('Светлая')).characters=item.title;ts.find(c=>c.characters.includes('Москва ·')).characters=item.city;ts.find(c=>c.characters.includes('15 октября')).characters=item.tag;ts.find(c=>c.characters.includes('Аня,')).characters=item.who;ts.find(c=>c.characters==='А').characters=item.initial;parent.appendChild(n);return n;}

